parameters.functionScript:
if (!Inputs.items || !Inputs.items.length) {
  Outputs.list = 'No saved articles yet.';
  return;
}
Outputs.list = Inputs.items.map(function(it){
  var d = new Date(it.savedAt);
  var ds = isNaN(d.getTime()) ? '' : d.toLocaleDateString();
  return (it.title || 'Untitled') + '  —  ' + ds;
}).join('\n');
